/* Native creator Channel owner.
 *
 * A channel composes a creator's published MediaPrograms into a browsable
 * surface and owns only ChannelSubscription. CMS remains the publication and
 * representation owner; Community owns comments; MediaLibrary/Delivery own
 * access, playback planning and transport; counters and watch proof are not
 * inferred from a channel listing or a subscription. */
#define _POSIX_C_SOURCE 200809L
#include <sqlite3.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/wait.h>
#include <time.h>
#include <unistd.h>

static const char *arg(int ac,char **av,const char *name){for(int i=2;i+1<ac;i++)if(!strcmp(av[i],name))return av[i+1];return 0;}
static int atom(const char*s){if(!s||!*s||strlen(s)>255)return 0;for(;*s;s++)if(!((*s>='a'&&*s<='z')||(*s>='A'&&*s<='Z')||(*s>='0'&&*s<='9')||*s==':'||*s=='-'||*s=='_'||*s=='.'||*s=='/'))return 0;return 1;}
static void js(const char*s){const unsigned char*p=(const unsigned char*)(s?s:"");putchar('"');for(;*p;p++){if(*p=='"'||*p=='\\'){putchar('\\');putchar(*p);}else if(*p<32)printf("\\u%04x",*p);else putchar(*p);}putchar('"');}
static int sql(sqlite3*d,const char*s){char*e=0;int ok=sqlite3_exec(d,s,0,0,&e)==SQLITE_OK;if(!ok){fprintf(stderr,"sqlite: %s\n",e?e:"error");sqlite3_free(e);}return ok;}
static int open_db(const char*p,sqlite3**d){if(!p||sqlite3_open_v2(p,d,SQLITE_OPEN_READWRITE|SQLITE_OPEN_CREATE,0)!=SQLITE_OK)return 0;sqlite3_busy_timeout(*d,5000);return sql(*d,"PRAGMA journal_mode=WAL;CREATE TABLE IF NOT EXISTS creator_channel(channel_id TEXT PRIMARY KEY,owner_subject TEXT NOT NULL,display_name TEXT NOT NULL,handle TEXT NOT NULL UNIQUE,visibility TEXT NOT NULL CHECK(visibility IN('public','unlisted','private')),community_ref TEXT NOT NULL DEFAULT '',state TEXT NOT NULL CHECK(state IN('active','retired')),updated_at INTEGER NOT NULL);CREATE TABLE IF NOT EXISTS channel_publication(channel_id TEXT NOT NULL REFERENCES creator_channel(channel_id),subject_ref TEXT NOT NULL,media_program_ref TEXT NOT NULL,program_kind TEXT NOT NULL CHECK(program_kind IN('video','short','live')),state TEXT NOT NULL CHECK(state IN('published','removed')),published_at INTEGER NOT NULL,PRIMARY KEY(channel_id,subject_ref,media_program_ref));CREATE TABLE IF NOT EXISTS channel_subscription(channel_id TEXT NOT NULL REFERENCES creator_channel(channel_id),actor_subject TEXT NOT NULL,state TEXT NOT NULL CHECK(state IN('active','unsubscribed')),updated_at INTEGER NOT NULL,PRIMARY KEY(channel_id,actor_subject));CREATE INDEX IF NOT EXISTS channel_publication_surface ON channel_publication(channel_id,state,published_at DESC);CREATE INDEX IF NOT EXISTS channel_subscription_actor ON channel_subscription(actor_subject,state,updated_at DESC);");}
static int stdin_token(char*out,size_t cap){size_t n=0;int c;if(!out||cap<2)return 0;while((c=fgetc(stdin))!=EOF){if(c=='\n'||c=='\r')break;if(c<0x21||c>0x7e||n+1>=cap)return 0;out[n++]=(char)c;}out[n]=0;return n>0;}
static int jstr(const char*j,const char*k,char*out,size_t cap){char n[96];const char*p;size_t z=0;if(!j||!k||!out||snprintf(n,sizeof(n),"\"%s\"",k)>=(int)sizeof(n))return 0;p=strstr(j,n);if(!p||(p=strchr(p+strlen(n),':'))==0)return 0;while(*++p==' '||*p=='\n'||*p=='\r'||*p=='\t'){}if(*p++!='"')return 0;while(*p&&*p!='"'){if(*p=='\\'&&!*++p)return 0;if((unsigned char)*p<32||z+1>=cap)return 0;out[z++]=*p++;}if(*p!='"'||!z)return 0;out[z]=0;return 1;}
static int child_auth(const char*bin,const char*db,const char*token,char*actor,size_t cap){int in[2],out[2],st=0;pid_t p;char b[2048];size_t n=0;ssize_t r;char*const av[]={(char*)bin,"--db",(char*)db,"actor-closure-stdin",0};if(!bin||!db||!token||pipe(in)||pipe(out))return 0;p=fork();if(p<0)return 0;if(!p){close(in[1]);close(out[0]);if(dup2(in[0],0)<0||dup2(out[1],1)<0)_exit(127);close(in[0]);close(out[1]);execvp(bin,av);_exit(127);}close(in[0]);close(out[1]);if(write(in[1],token,strlen(token))!=(ssize_t)strlen(token)||write(in[1],"\n",1)!=1){close(in[1]);close(out[0]);waitpid(p,&st,0);return 0;}close(in[1]);while(n+1<sizeof(b)&&(r=read(out[0],b+n,sizeof(b)-1-n))>0)n+=(size_t)r;close(out[0]);b[n]=0;return waitpid(p,&st,0)>=0&&WIFEXITED(st)&&WEXITSTATUS(st)==0&&jstr(b,"actor_subject",actor,cap)&&atom(actor);}
static int channel_owner(sqlite3*d,const char*id,const char*actor){sqlite3_stmt*s=0;int ok=0;if(sqlite3_prepare_v2(d,"SELECT 1 FROM creator_channel WHERE channel_id=?1 AND state='active' AND owner_subject=?2",-1,&s,0)!=SQLITE_OK)return 0;sqlite3_bind_text(s,1,id,-1,0);sqlite3_bind_text(s,2,actor,-1,0);ok=sqlite3_step(s)==SQLITE_ROW;sqlite3_finalize(s);return ok;}
static int cmd_put(sqlite3*d,int ac,char**av){const char*id=arg(ac,av,"--id"),*owner=arg(ac,av,"--owner"),*name=arg(ac,av,"--name"),*handle=arg(ac,av,"--handle"),*vis=arg(ac,av,"--visibility"),*community=arg(ac,av,"--community"),*by=arg(ac,av,"--by");sqlite3_stmt*s=0;int ok;if(!atom(id)||!atom(owner)||!name||!atom(handle)||!vis||!atom(by)||strcmp(owner,by)||(strcmp(vis,"public")&&strcmp(vis,"unlisted")&&strcmp(vis,"private")))return 0;if(!community)community="";if(!atom(community)&&*community)return 0;if(sqlite3_prepare_v2(d,"INSERT INTO creator_channel VALUES(?1,?2,?3,?4,?5,?6,'active',?7) ON CONFLICT(channel_id) DO UPDATE SET display_name=excluded.display_name,handle=excluded.handle,visibility=excluded.visibility,community_ref=excluded.community_ref,updated_at=excluded.updated_at WHERE creator_channel.owner_subject=excluded.owner_subject",-1,&s,0)!=SQLITE_OK)return 0;sqlite3_bind_text(s,1,id,-1,0);sqlite3_bind_text(s,2,owner,-1,0);sqlite3_bind_text(s,3,name,-1,0);sqlite3_bind_text(s,4,handle,-1,0);sqlite3_bind_text(s,5,vis,-1,0);sqlite3_bind_text(s,6,community,-1,0);sqlite3_bind_int64(s,7,time(0));ok=sqlite3_step(s)==SQLITE_DONE&&sqlite3_changes(d)==1;sqlite3_finalize(s);if(ok){fputs("{\"schema\":\"bonfyre-creator-channel.v1\",\"channel_id\":",stdout);js(id);fputs(",\"state\":\"active\",\"truth\":\"channel_program_not_media_identity_or_delivery\"}\n",stdout);}return ok;}
static int published_program(const char*cms,const char*program,const char*subject){sqlite3*d=0;sqlite3_stmt*s=0;int ok=0;if(!cms||sqlite3_open_v2(cms,&d,SQLITE_OPEN_READONLY,0)!=SQLITE_OK)return 0;if(sqlite3_prepare_v2(d,"SELECT 1 FROM media_program WHERE program_id=?1 AND subject_ref=?2 AND publication_state='published' AND status='published'",-1,&s,0)==SQLITE_OK){sqlite3_bind_text(s,1,program,-1,0);sqlite3_bind_text(s,2,subject,-1,0);ok=sqlite3_step(s)==SQLITE_ROW;sqlite3_finalize(s);}sqlite3_close(d);return ok;}
static int cmd_publish(sqlite3*d,int ac,char**av){const char*cms=arg(ac,av,"--cms-db"),*id=arg(ac,av,"--channel"),*sub=arg(ac,av,"--subject"),*program=arg(ac,av,"--program"),*kind=arg(ac,av,"--kind"),*by=arg(ac,av,"--by");sqlite3_stmt*s=0;int ok;if(!cms||!atom(id)||!atom(sub)||!atom(program)||!atom(by)||!channel_owner(d,id,by)||!kind||(strcmp(kind,"video")&&strcmp(kind,"short")&&strcmp(kind,"live"))||!published_program(cms,program,sub))return 0;if(sqlite3_prepare_v2(d,"INSERT INTO channel_publication VALUES(?1,?2,?3,?4,'published',?5) ON CONFLICT(channel_id,subject_ref,media_program_ref) DO UPDATE SET program_kind=excluded.program_kind,state='published',published_at=excluded.published_at",-1,&s,0)!=SQLITE_OK)return 0;sqlite3_bind_text(s,1,id,-1,0);sqlite3_bind_text(s,2,sub,-1,0);sqlite3_bind_text(s,3,program,-1,0);sqlite3_bind_text(s,4,kind,-1,0);sqlite3_bind_int64(s,5,time(0));ok=sqlite3_step(s)==SQLITE_DONE;sqlite3_finalize(s);if(ok){fputs("{\"schema\":\"bonfyre-channel-publication.v1\",\"channel_id\":",stdout);js(id);fputs(",\"media_program_ref\":",stdout);js(program);fputs(",\"state\":\"published\",\"truth\":\"channel_membership_not_delivery_right_or_watch_proof\"}\n",stdout);}return ok;}
static int channel_visible(sqlite3*d,const char*id,const char*actor){sqlite3_stmt*s=0;int ok=0;if(sqlite3_prepare_v2(d,"SELECT 1 FROM creator_channel WHERE channel_id=?1 AND state='active' AND (visibility IN ('public','unlisted') OR owner_subject=?2 OR EXISTS(SELECT 1 FROM channel_subscription WHERE channel_id=creator_channel.channel_id AND actor_subject=?2 AND state='active'))",-1,&s,0)!=SQLITE_OK)return 0;sqlite3_bind_text(s,1,id,-1,0);sqlite3_bind_text(s,2,actor?actor:"anonymous",-1,0);ok=sqlite3_step(s)==SQLITE_ROW;sqlite3_finalize(s);return ok;}
static int cmd_subscribe(sqlite3*d,int ac,char**av,int active){const char*id=arg(ac,av,"--channel"),*adb=arg(ac,av,"--auth-db"),*auth=getenv("BONFYRE_AUTH_BIN");char token[192],actor[256];sqlite3_stmt*s=0;int ok;if(!auth||!*auth)auth="bonfyre-auth";if(!atom(id)||!adb||!stdin_token(token,sizeof(token))||!child_auth(auth,adb,token,actor,sizeof(actor))||!channel_visible(d,id,actor))return 0;if(sqlite3_prepare_v2(d,"INSERT INTO channel_subscription VALUES(?1,?2,?3,?4) ON CONFLICT(channel_id,actor_subject) DO UPDATE SET state=excluded.state,updated_at=excluded.updated_at",-1,&s,0)!=SQLITE_OK)return 0;sqlite3_bind_text(s,1,id,-1,0);sqlite3_bind_text(s,2,actor,-1,0);sqlite3_bind_text(s,3,active?"active":"unsubscribed",-1,0);sqlite3_bind_int64(s,4,time(0));ok=sqlite3_step(s)==SQLITE_DONE;sqlite3_finalize(s);if(ok){fputs("{\"schema\":\"bonfyre-channel-subscription.v1\",\"channel_id\":",stdout);js(id);fputs(",\"actor_subject\":",stdout);js(actor);fputs(",\"state\":",stdout);js(active?"active":"unsubscribed");fputs(",\"truth\":\"channel_subscription_not_notification_delivery_or_relationship_authority\"}\n",stdout);}return ok;}
static int cmd_surface(sqlite3*d,int ac,char**av){const char*cms=arg(ac,av,"--cms-db"),*id=arg(ac,av,"--channel"),*actor=arg(ac,av,"--actor");sqlite3_stmt*c=0,*p=0;sqlite3*cd=0;int first=1;if(!cms||!atom(id)||!channel_visible(d,id,actor)||sqlite3_open_v2(cms,&cd,SQLITE_OPEN_READONLY,0)!=SQLITE_OK)return 0;if(sqlite3_prepare_v2(d,"SELECT display_name,handle,visibility,community_ref FROM creator_channel WHERE channel_id=?1",-1,&c,0)!=SQLITE_OK)goto fail;sqlite3_bind_text(c,1,id,-1,0);if(sqlite3_step(c)!=SQLITE_ROW)goto fail;fputs("{\"schema\":\"bonfyre-channel-surface.v1\",\"channel_id\":",stdout);js(id);fputs(",\"display_name\":",stdout);js((const char*)sqlite3_column_text(c,0));fputs(",\"handle\":",stdout);js((const char*)sqlite3_column_text(c,1));fputs(",\"visibility\":",stdout);js((const char*)sqlite3_column_text(c,2));fputs(",\"community_ref\":",stdout);js((const char*)sqlite3_column_text(c,3));fputs(",\"navigation\":[\"Home\",\"Videos\",\"Shorts\",\"Live\",\"Playlists\",\"Community\",\"About\"],\"programs\":[",stdout);if(sqlite3_prepare_v2(d,"SELECT subject_ref,media_program_ref,program_kind,published_at FROM channel_publication WHERE channel_id=?1 AND state='published' ORDER BY published_at DESC LIMIT 96",-1,&p,0)!=SQLITE_OK)goto fail;sqlite3_bind_text(p,1,id,-1,0);while(sqlite3_step(p)==SQLITE_ROW){const char*sub=(const char*)sqlite3_column_text(p,0),*program=(const char*)sqlite3_column_text(p,1);sqlite3_stmt*check=0;int current=0;if(sqlite3_prepare_v2(cd,"SELECT 1 FROM media_program WHERE program_id=?1 AND subject_ref=?2 AND publication_state='published' AND status='published'",-1,&check,0)==SQLITE_OK){sqlite3_bind_text(check,1,program,-1,0);sqlite3_bind_text(check,2,sub,-1,0);current=sqlite3_step(check)==SQLITE_ROW;sqlite3_finalize(check);}if(!current)continue;if(!first)putchar(',');first=0;fputs("{\"subject_ref\":",stdout);js(sub);fputs(",\"media_program_ref\":",stdout);js(program);fputs(",\"kind\":",stdout);js((const char*)sqlite3_column_text(p,2));printf(",\"published_at\":%lld}",sqlite3_column_int64(p,3));}fputs("],\"truth\":\"channel_surface_of_currently_published_programs_only_no_bytes_delivery_views_or_watch_proof\"}\n",stdout);sqlite3_finalize(c);sqlite3_finalize(p);sqlite3_close(cd);return 1;fail:if(c)sqlite3_finalize(c);if(p)sqlite3_finalize(p);if(cd)sqlite3_close(cd);return 0;}
static int cmd_auth_surface(sqlite3*d,int ac,char**av){char token[192],actor[256];const char*adb=arg(ac,av,"--auth-db"),*auth=getenv("BONFYRE_AUTH_BIN");char*copy[128];int n=0;if(!auth||!*auth)auth="bonfyre-auth";if(!adb||!stdin_token(token,sizeof(token))||!child_auth(auth,adb,token,actor,sizeof(actor))||ac+2>(int)(sizeof(copy)/sizeof(*copy)))return 0;for(int i=0;i<ac;i++)copy[n++]=av[i];copy[n++]="--actor";copy[n++]=actor;return cmd_surface(d,n,copy);}
static int cmd_ads(sqlite3*d){sqlite3_stmt*s=0;int n=0;if(sqlite3_prepare_v2(d,"SELECT channel_id,visibility FROM creator_channel WHERE state='active'",-1,&s,0)!=SQLITE_OK)return 0;while(sqlite3_step(s)==SQLITE_ROW){const char*id=(const char*)sqlite3_column_text(s,0),*vis=(const char*)sqlite3_column_text(s,1);if(!id||!vis)continue;fputs("{\"identity\":\"channel:",stdout);fputs(id,stdout);fputs("\",\"candidate_kind\":\"surface_channel\",\"owner_ref\":\"CreatorChannel:",stdout);fputs(id,stdout);fputs("\",\"exact_verifier\":\"CreatorChannel:visibility\",\"lowerer_ref\":\"ChannelSurfaceCompiler:surface\",\"terms\":[\"material:media\",\"operation:watch\",\"extent:page\",\"visibility:",stdout);fputs(vis,stdout);fputs("\"]}\n",stdout);n++;}sqlite3_finalize(s);fprintf(stderr,"{\"schema\":\"bonfyre-channel-advertisements.v1\",\"emitted\":%d,\"truth\":\"forwarding_descriptors_only\"}\n",n);return n>0;}
static void use(void){fputs("bonfyre-channel put --db FILE --id ID --owner SUBJECT --name TEXT --handle HANDLE --visibility public|unlisted|private [--community SUBJECT] --by SUBJECT\n bonfyre-channel publish --db FILE --cms-db FILE --channel ID --subject SUBJECT --program PROGRAM --kind video|short|live --by SUBJECT\n bonfyre-channel authenticated-subscribe|authenticated-unsubscribe --db FILE --auth-db FILE --channel ID < bearer-token\n bonfyre-channel surface --db FILE --cms-db FILE --channel ID [--actor SUBJECT]  # internal/public projection\n bonfyre-channel authenticated-surface --db FILE --cms-db FILE --auth-db FILE --channel ID < bearer-token\n bonfyre-channel emit-advertisements --db FILE\n",stderr);}
int main(int ac,char**av){const char*db=arg(ac,av,"--db");sqlite3*d=0;int ok=0;if(ac<2||!db){use();return 2;}if(!open_db(db,&d))return 1;if(!strcmp(av[1],"put"))ok=cmd_put(d,ac,av);else if(!strcmp(av[1],"publish"))ok=cmd_publish(d,ac,av);else if(!strcmp(av[1],"authenticated-subscribe"))ok=cmd_subscribe(d,ac,av,1);else if(!strcmp(av[1],"authenticated-unsubscribe"))ok=cmd_subscribe(d,ac,av,0);else if(!strcmp(av[1],"surface"))ok=cmd_surface(d,ac,av);else if(!strcmp(av[1],"authenticated-surface"))ok=cmd_auth_surface(d,ac,av);else if(!strcmp(av[1],"emit-advertisements"))ok=cmd_ads(d);else{use();sqlite3_close(d);return 2;}sqlite3_close(d);return ok?0:1;}
